{
  "name": "shodh-cloudflare-mcp",
  "version": "2.0.0",
  "description": "MCP bridge for SHODH on Cloudflare",
  "type": "module",
  "main": "index.js",
  "bin": {
    "shodh-cloudflare-mcp": "./index.js"
  },
  "scripts": {
    "start": "node index.js"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": ">=1.8.0"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}

{
  "name": "shodh-cloudflare-worker",
  "version": "2.1.0",
  "description": "SHODH Memory API on Cloudflare Workers",
  "main": "src/index.ts",
  "scripts": {
    "dev": "wrangler dev",
    "deploy": "wrangler deploy",
    "tail": "wrangler tail",
    "test": "vitest",
    "test:ui": "vitest --ui",
    "test:coverage": "vitest --coverage"
  },
  "dependencies": {
    "hono": "^4.6.0"
  },
  "devDependencies": {
    "@cloudflare/workers-types": "^4.20260702.1",
    "@vitest/coverage-v8": "^1.2.0",
    "@vitest/ui": "^1.2.0",
    "typescript": "^5.7.0",
    "vitest": "^1.2.0",
    "wrangler": "^4.56.0"
  }
}

